  height: auto;
  filter: drop-shadow(0 0 10px #fd1853);
  z-index: 2;
}

.__UIV_SCOPE__ button:hover .star-5 {
  position: absolute;
  top: 25%;
  left: 115%;
  width: 15px;
  height: auto;
  filter: drop-shadow(0 0 10px #fd1853);
